package com.huiqiyikang.assessment.mapper; import com.huiqiyikang.assessment.entity.AssessmentTask; import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import java.util.*; public interface AssessmentTaskRepository extends BaseMapperX<AssessmentTask>{default List<AssessmentTask> findByClassIdAndStatus(Long id,String status){return selectList(new QueryWrapper<AssessmentTask>().eq("class_id",id).eq("status",status));}}
